select (select count(*) from auth.users where id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db') as auth_users, (select count(*) from public.profiles where id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db') as profiles, (select count(*) from public.financial_cases where owner_id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db') as cases, (select count(*) from private.input_objects where owner_id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db' and deleted_at is null) as active_inputs, (select count(*) from private.ocr_artifacts where owner_id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db' and deleted_at is null) as active_ocr, (select count(*) from private.case_embeddings where owner_id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db') as embeddings, (select count(*) from storage.objects where bucket_id='finshield-quarantine' and name like 'bf2d2ec2-eda1-4326-b99c-ba6030a1f6db/%') as storage_objects, (select count(*) from public.deletion_requests where owner_id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db' and status<>'COMPLETED') as pending_requests, (select count(*) from private.deletion_ledger l join public.deletion_requests r on r.id=l.deletion_request_id where r.owner_id='bf2d2ec2-eda1-4326-b99c-ba6030a1f6db' and l.target_type='ACCOUNT' and l.event_type='COMPLETED') as account_completed_events;